fn read(p:impl AsRef<Path>)->Value {serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value) {fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn hash(p:impl AsRef<Path>)->String {let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn pin(m:&mut BTreeMap<String,String>,p:impl AsRef<Path>){let p=p.as_ref();m.insert(p.display().to_string(),hash(p));}
fn cases()->Vec<(String,usize,usize)> {[200,352].into_iter().flat_map(|n|[0,5,8,13,16,32].map(move|m|(format!("n{n}-m{m}"),n,m))).collect()}
fn environment()->BTreeMap<String,String> {[("ZOPRO_CPU_G2_PREFIX_RECORDS","1"),("ZOPRO_CPU_DIRECT","1"),("ZOPRO_CPU_CANONICAL_BATCH","1"),("ZOPRO_CPU_VECTOR_INVERSE","1"),("ZOPRO_CPU_G1_SCRATCH_STORE","2"),("RAYON_NUM_THREADS","1"),("MALLOC_ARENA_MAX","32"),("MALLOC_MMAP_THRESHOLD_","1073741824"),("MALLOC_TRIM_THRESHOLD_","-1")].into_iter().map(|(k,v)|(k.into(),v.into())).collect()}
fn step(name:String,argv:Vec<String>)->Value {json!({"kind":"command","name":name,"argv":argv,"timeout_seconds":240})}
fn prepare() {
    let r=Path::new(R);assert!(!r.join("run-plan.json").exists());let tests=fs::read_to_string(r.join("tests.log")).unwrap();assert!(tests.contains("test result: ok. 2 passed; 0 failed"));
    assert!(fs::read_to_string(r.join("control-tests.log")).unwrap().contains("test result: ok. 1 passed; 0 failed"));
    let mut pins=BTreeMap::new();let mut changed=Vec::new();let m=read(format!("{Z}/docs/benchmarks/2026-10-27-clean-fft-adoption/artifacts/production-source-manifest.json"));
    for (f,h) in m["source_files_sha256"].as_object().unwrap() {let p=Path::new(Z).join(f);assert_eq!(hash(&p),h.as_str().unwrap());pin(&mut pins,p);let local=r.join("source").join(f);pin(&mut pins,&local);if hash(&local)!=h.as_str().unwrap(){changed.push(f.clone());}}
    assert_eq!(changed,["crates/zopro-core/src/lib.rs","crates/zopro-core/src/msm.rs"]);
    for (f,suffix) in [("crates/zopro-core/src/msm.rs","\n#[cfg(zopro_mixed_probe)]\nmod mixed_probe;\n#[cfg(zopro_mixed_probe)]\npub use mixed_probe::MixedCaller;\n"),("crates/zopro-core/src/lib.rs","\n#[cfg(zopro_mixed_probe)]\npub use msm::MixedCaller;\n")] {let s=fs::read_to_string(r.join("source").join(f)).unwrap();assert_eq!(s.strip_suffix(suffix).unwrap(),fs::read_to_string(Path::new(Z).join(f)).unwrap());}
    let module=r.join("source/crates/zopro-core/src/msm/mixed_probe.rs");assert_eq!(hash(&module),hash(r.join("mixed_probe.rs")));pin(&mut pins,module);assert_eq!(hash(r.join("src/bin/probe.rs")),hash(r.join("probe.rs")));
    for f in ["design.md","design-initial.md","control.rs","control","probe.rs","src/bin/probe.rs","probe-first-build.rs","probe-qualified-v1.rs","mixed-qualified-v1.rs","qualified-tests-v1","mixed_probe.rs","native-flags.txt","Cargo.toml","Cargo.lock","test-build.log","test-build-repaired.log","tests.log","control-tests.log","probe-build.log","probe","host.txt","rustc.txt"] {pin(&mut pins,r.join(f));}
    for e in fs::read_dir(r.join("target/release/deps")).unwrap() {let e=e.unwrap();let name=e.file_name().to_string_lossy().to_string();if name.ends_with(".rlib")||(name.starts_with("probe-")&&!name.ends_with(".d")){pin(&mut pins,e.path());}}
    pin(&mut pins,X);let cs=cases();let mut steps=Vec::new();
    for (c,n,m) in &cs {for v in ["binary","mixed"] {steps.push(step(format!("preflight-{c}-{v}"),vec!["taskset".into(),"-c".into(),"2".into(),format!("{R}/probe"),n.to_string(),m.to_string(),"17".into(),v.into()]));}}
    for b in 0..31 {let mut order:Vec<_>=cs.iter().flat_map(|c|["binary","mixed"].map(move|v|(c,v))).collect();let len=order.len();order.rotate_left(b*11%len);if b%2!=0{order.reverse();}
        for ((c,n,m),v) in order {steps.push(step(format!("lat-b{b:02}-{c}-{v}"),vec!["taskset".into(),"-c".into(),"2".into(),format!("{R}/probe"),n.to_string(),m.to_string(),"4096".into(),v.into()]));}
    }
    let env=environment();
    for (n,m) in [(200,13),(352,16)] {for v in ["binary","mixed"] {let key=format!("n{n}-m{m}-{v}");let p=r.join("profiles").join(&key);fs::create_dir_all(&p).unwrap();let mut argv=vec!["sudo".into(),"-n".into(),"env".into()];argv.extend(env.iter().map(|(k,v)|format!("{k}={v}")));argv.extend(["perf".into(),"record".into(),"--no-buildid-cache".into(),"-e".into(),"cycles:u".into(),"-F".into(),"199".into(),"-o".into(),p.join("perf.data").display().to_string(),"--".into(),"taskset".into(),"-c".into(),"2".into(),format!("{R}/probe"),n.to_string(),m.to_string(),"262144".into(),v.into()]);steps.push(step(format!("profile-{key}"),argv));}}
    for (n,m) in [(200,13),(352,16)] {for v in ["binary","mixed"] {let key=format!("n{n}-m{m}-{v}");let file=format!("{R}/profiles/{key}/perf.data");steps.push(step(format!("owner-{key}"),vec!["sudo".into(),"-n".into(),"chown".into(),"ubuntu:ubuntu".into(),file.clone()]));steps.push(step(format!("decode-{key}"),vec!["perf".into(),"script".into(),"--header".into(),"-i".into(),file.clone(),"-F".into(),"pid,tid,period,ip,sym,dso".into()]));steps.push(step(format!("loss-{key}"),vec!["perf".into(),"script".into(),"-D".into(),"-i".into(),file]));}}
    save(r.join("pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"production_files_unchanged":172,"private_original_files_unchanged":170,"changed_original_files":changed,"inverse_edits_recover":true,"field_backend_changed":false,"new_module":"msm/mixed_probe.rs"}));
    save(r.join("run-plan.json"),&json!({"version":1,"source_pins":r.join("pins.json"),"environment":env,"steps":steps}));
    save(r.join("declaration.json"),&json!({"cases":cs,"blocks":31,"latency_processes":744,"preflights":24,"profiles":4,"iterations":4096,"prime_calls":3,"prime_rounds":8,"pin_count":pins.len(),"control":"two explicit original signed-borrowed layers; selection/R-list assembly before timer; not actual delayed production queue schedule","gate":"zero collision calibration withinfactor1.03; percaseupper<1>=21wins for nonzero collisions","SDK_requests":0,"proof_ledger":12527,"goal_achieved":false}));println!("Prepared744latency+24preflight+4profiles;{}pins",pins.len());
}
fn result(name:&str)->Value {let s=fs::read_to_string(format!("{R}/runs/{name}/stdout.log")).unwrap();let lines:Vec<_>=s.lines().filter_map(|s|s.strip_prefix("RESULT ")).collect();assert_eq!(lines.len(),1);let v:Value=serde_json::from_str(lines[0]).unwrap();assert_eq!(v["internally_verified"],true);assert_eq!(v["timed_allocations"],0);v}
fn stats(mut values:Vec<f64>)->Value {assert_eq!(values.len(),31);let all=values.clone();values.sort_by(f64::total_cmp);json!({"median":values[15],"low":values[9],"high":values[21],"wins":values.iter().filter(|&&x|x<1.).count(),"all_ratios":all})}
fn median(mut v:Vec<f64>)->f64 {v.sort_by(f64::total_cmp);v[v.len()/2]}
fn archive(root:&Path,dir:&Path,dest:&Path,index:&mut BTreeMap<String,String>) {for e in fs::read_dir(dir).unwrap() {let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();if e.file_type().unwrap().is_dir(){if ["source","target","profiles"].contains(&name.as_str()){continue;}archive(root,&p,dest,index);}else if ["rs","json","md","log","toml","lock","txt","s"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or(""))&&! ["workflow.log","close.log","archive-verification.log"].contains(&name.as_str()){let rel=p.strip_prefix(root).unwrap();let out=dest.join(rel);fs::create_dir_all(out.parent().unwrap()).unwrap();fs::copy(&p,&out).unwrap();index.insert(format!("artifacts/{}",rel.display()),hash(out));}}}
fn finish() {
    let r=Path::new(R);for (p,h) in read(r.join("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}assert_eq!(read(r.join("runs/result.json"))["status"],"complete");
    let mut rows=Vec::new();let mut passing=Vec::new();let mut calibration=Vec::new();
    for (c,n,m) in cases() {for v in ["binary","mixed"] {assert_eq!(result(&format!("preflight-{c}-{v}"))["iterations"],17);}
        let mut times=BTreeMap::new();let mut memory=BTreeMap::new();let mut output=None;let mut queue=None;
        for variant in ["binary","mixed"] {let mut t=Vec::new();for b in 0..31 {let v=result(&format!("lat-b{b:02}-{c}-{variant}"));assert_eq!(v["iterations"],4096);assert_eq!(v["selected_entries"],m);if let Some(h)=&output {assert_eq!(h,&v["output_sha256"]);}else{output=Some(v["output_sha256"].clone());}
            let mem=json!({"mixed_scratch_capacity_bytes":v["mixed_scratch_capacity_bytes"],"control_scratch_capacity_bytes":v["control_scratch_capacity_bytes"]});if let Some(old)=memory.get(variant){assert_eq!(old,&mem);}else{memory.insert(variant,mem);}
            let q=json!({"entries":v["queue_entries"],"selected":v["selected_entries"],"remaining":v["leftover_entries"]});if let Some(old)=&queue {assert_eq!(old,&q);}else{queue=Some(q);}
            t.push(v["ns_per_round"].as_f64().unwrap());}times.insert(variant,t);}
        let ratio=stats(times["mixed"].iter().zip(&times["binary"]).map(|(a,b)|a/b).collect());let pass=m>0&&ratio["high"].as_f64().unwrap()<1.&&ratio["wins"].as_u64().unwrap()>=21;if pass {passing.push(c.clone());}
        if m==0&&(ratio["low"].as_f64().unwrap()<1./1.03||ratio["high"].as_f64().unwrap()>1.03){calibration.push(c.clone());}
        rows.push(json!({"case":c,"pending":n,"collisions":m,"binary_median_ns":median(times["binary"].clone()),"mixed_median_ns":median(times["mixed"].clone()),"mixed_vs_binary":ratio,"caller_gain":pass,"scratch":memory,"queue":queue,"output_sha256":output}));
    }
    let mut profiles=BTreeMap::new();let mut raw=BTreeMap::new();
    for (n,m) in [(200,13),(352,16)] {for variant in ["binary","mixed"] {let key=format!("n{n}-m{m}-{variant}");let output=result(&format!("profile-{key}"));assert_eq!(output["iterations"],262144);
        let decode=fs::read_to_string(r.join(format!("runs/decode-{key}/stdout.log"))).unwrap();let loss=r.join(format!("runs/loss-{key}/stdout.log"));assert!(!fs::read_to_string(&loss).unwrap().contains("PERF_RECORD_LOST"));let mut pids=BTreeSet::new();let mut samples=0;let mut period=0;let mut symbols=BTreeMap::<String,u64>::new();
        for line in decode.lines().filter(|l|!l.trim_start().starts_with('#')){let w:Vec<_>=line.split_whitespace().collect();if w.len()<5{continue;}let parsed=if let Some((pid,_))=w[0].split_once('/') {pid.parse::<u64>().ok().zip(w[1].parse::<u64>().ok()).map(|(p,n)|(p,n,3))}else if w.len()>=6{w[0].parse::<u64>().ok().zip(w[2].parse::<u64>().ok()).map(|(p,n)|(p,n,4))}else{None};if let Some((p,n,start))=parsed{pids.insert(p);samples+=1;period+=n;*symbols.entry(w[start..].join(" ")).or_default()+=n;}}
        assert!(samples>0);assert_eq!(pids.len(),1);pin(&mut raw,r.join(format!("profiles/{key}/perf.data")));pin(&mut raw,loss);profiles.insert(key,json!({"samples":samples,"period":period,"pids":pids,"lost":0,"symbols":symbols,"output":output}));
    }}
    let asm=fs::read_to_string(r.join("assembly.local")).unwrap();let mut name=String::new();let mut lines=Vec::new();let mut hot=String::new();let mut functions=Vec::new();let mut emit=|name:&str,lines:&Vec<String>|{if ["mixed_probe::mixed","mixed_probe::baseline","mixed_probe::MixedScratch","mixed_probe::Borrowed","stream_g1_impl"].iter().any(|s|name.contains(s)){hot.push_str(name);hot.push('\n');for l in lines{hot.push_str(l);hot.push('\n');}functions.push(json!({"symbol":name,"instruction_sites":lines.len(),"IFMA_sites":lines.iter().filter(|l|l.contains("vpmadd52")).count(),"RSP_operand_lines":lines.iter().filter(|l|l.contains("%rsp")).count()}));}};
    for line in asm.lines(){if line.ends_with(">:"){emit(&name,&lines);name=line.into();lines.clear();}else if line.contains(':')&&!line.trim().is_empty(){lines.push(line.into());}}emit(&name,&lines);fs::write(r.join("hot.s"),hot).unwrap();
    let gate=calibration.is_empty()&&!passing.is_empty();save(r.join("analysis.json"),&json!({"status":"complete mixed native caller experiment","gate_passed":gate,"passing_cases":passing,"calibration_failures":calibration,"rows":rows,"profiles":profiles,"raw_profile_pins":raw,"static_code":{"full_assembly_sha256":hash(r.join("assembly.local")),"functions":functions},"new_tests":3,"latency_processes":744,"preflights":24,"profile_processes":4,"timed_allocations":0,"all_outputs_verified":true,"leftover_queue_order_verified":true,"SDK_requests":0,"new_exports":0,"proof_ledger":12527,"production_changed":false,"adopted":false,"goal_achieved":false,"limits":"Representative modeled batches, two-explicit-layer control with preselection outside timing. Actual delayed production schedule, reduced flush count, SDK speed, peakRSS, pressure, phones,TEE,AWS and Aeglos unqualified."}));
    let dest=Path::new(D);fs::create_dir_all(dest.join("artifacts")).unwrap();for f in ["crates/zopro-core/src/lib.rs","crates/zopro-core/src/msm.rs","crates/zopro-core/src/msm/mixed_probe.rs"] {let out=r.join("candidate-source").join(f);fs::create_dir_all(out.parent().unwrap()).unwrap();fs::copy(r.join("source").join(f),out).unwrap();}
    let mut index=BTreeMap::new();archive(r,r,&dest.join("artifacts"),&mut index);save(dest.join("artifact-index.json"),&json!(index));fs::write(dest.join("SHA256SUMS"),index.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();println!("Closed mixed callers:gate{gate};{}archivehashes;ledger12527unchanged",index.len());
}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("finish")=>finish(),_=>panic!("prepare/finish")}}
